<style>
.pl-hero{background:linear-gradient(135deg,#351528 0%,#6d2940 62%,#a77522 130%);border:0;color:#fff;overflow:hidden;position:relative}.pl-hero:after{content:'PK';position:absolute;right:20px;top:-42px;font:900 160px Georgia;color:rgba(255,255,255,.06)}.pl-hero .metric{background:rgba(255,255,255,.1);border:1px solid rgba(255,255,255,.14);border-radius:12px;padding:12px 16px}.pl-check{width:18px;height:18px}.pl-thumb{align-items:center;background:#f4f1f2;border:1px solid #e7dfe2;border-radius:10px;display:flex;height:54px;justify-content:center;overflow:hidden;width:64px}.pl-thumb img{height:100%;object-fit:cover;width:100%}.pl-selected{background:#fff8dd!important}.pl-bar{position:sticky;bottom:12px;z-index:5}
