<div class="card pl-hero mb-4"><div class="card-body p-4 p-lg-5 position-relative"><div class="row align-items-center g-3"><div class="col"><div class="text-uppercase small fw-bold mb-2" style="letter-spacing:2px;color:#e7bd68">Ready order dispatch</div><h2 class="mb-2 text-white">Packing List Generator</h2><p class="mb-0 text-white-50">Select multiple received and completed orders, then download one horizontal packing sheet.</p></div><div class="col-auto"><div class="metric"><div class="small text-white-50">AVAILABLE</div><div class="fs-3 fw-bold"><?= count($orders ?? []) ?></div></div></div></div></div></div>

<?php if (session()->getFlashdata('error')): ?><div class="alert alert-danger"><?= esc((string) session()->getFlashdata('error')) ?></div><?php endif; ?>

<form method="post" action="<?= site_url('admin/packing-lists/pdf') ?>" target="_blank" id="packingListForm">
    <?= csrf_field() ?>
    <div class="card"><div class="card-header"><div class="row g-2 align-items-center"><div class="col-md"><h5 class="mb-1">Completed &amp; Received Orders</h5><div class="text-muted small">Only orders with a saved receiving entry are eligible.</div></div><div class="col-md-4"><input class="form-control" type="search" id="packingSearch" placeholder="Search order, customer, karigar…"></div><div class="col-auto"><button class="btn btn-outline-secondary" type="button" id="selectVisible">Select visible</button></div></div></div>
    <div class="card-body p-0"><div class="table-responsive"><table class="table table-hover align-middle mb-0"><thead><tr><th style="width:48px"><input class="form-check-input pl-check" type="checkbox" id="selectAll"></th><th>Photo</th><th>Order</th><th>Customer</th><th>Karigar</th><th>Purity</th><th class="text-end">Gross</th><th class="text-end">Net</th><th class="text-end">Total Value</th><th>Received</th></tr></thead><tbody>
    <?php if (($orders ?? []) === []): ?><tr><td colspan="10" class="text-center text-muted py-5">No completed and received orders are available.</td></tr><?php endif; ?>
    <?php foreach (($orders ?? []) as $order): ?><tr class="js-order-row" data-search="<?= esc(strtolower(implode(' ', [(string) ($order['order_no'] ?? ''), (string) ($order['order_name'] ?? ''), (string) ($order['customer_name'] ?? ''), (string) ($order['karigar_name'] ?? '')])), 'attr') ?>">
        <td><input class="form-check-input pl-check js-order-check" type="checkbox" name="order_ids[]" value="<?= (int) $order['id'] ?>"></td>
        <td><span class="pl-thumb"><?php if (! empty($order['photo_url'])): ?><img src="<?= esc((string) $order['photo_url'], 'attr') ?>" alt="" onerror="this.remove()"><?php else: ?><i class="fe fe-image text-muted"></i><?php endif; ?></span></td>
        <td><strong><?= esc((string) $order['order_no']) ?></strong><div class="small text-muted"><?= esc((string) ($order['order_name'] ?? '')) ?></div></td>
        <td><?= esc((string) (($order['customer_name'] ?? '') ?: '-')) ?></td><td><?= esc((string) (($order['karigar_name'] ?? '') ?: '-')) ?></td><td><?= esc((string) (($order['purity_code'] ?? '') ?: '-')) ?></td>
        <td class="text-end"><?= number_format((float) ($order['gross_weight_gm'] ?? 0), 3) ?></td><td class="text-end"><?= number_format((float) ($order['net_gold_weight_gm'] ?? 0), 3) ?></td><td class="text-end fw-bold">₹<?= number_format((float) ($order['total_valuation'] ?? 0), 2) ?></td>
        <td><?= ! empty($order['received_at']) || ! empty($order['receipt_created_at']) ? date('d M Y', strtotime((string) (($order['received_at'] ?? '') ?: $order['receipt_created_at']))) : '-' ?></td>
    </tr><?php endforeach; ?>
    </tbody></table></div></div></div>
    <?php if (($orders ?? []) !== []): ?><div class="card pl-bar mt-3"><div class="card-body py-3 d-flex align-items-center justify-content-between"><div><strong id="selectedCount">0 selected</strong><div class="small text-muted">A4 landscape PDF · maximum 100 orders</div></div><button class="btn btn-primary" type="submit" id="generatePacking" disabled><i class="fe fe-download me-1"></i>Generate Packing List PDF</button></div></div><?php endif; ?>
</form>
<script>
document.addEventListener('DOMContentLoaded',function(){const rows=[...document.querySelectorAll('.js-order-row')],checks=[...document.querySelectorAll('.js-order-check')],all=document.getElementById('selectAll'),count=document.getElementById('selectedCount'),button=document.getElementById('generatePacking'),search=document.getElementById('packingSearch');const sync=()=>{const n=checks.filter(c=>c.checked).length;if(count)count.textContent=n+' selected';if(button)button.disabled=n===0;rows.forEach(r=>r.classList.toggle('pl-selected',r.querySelector('.js-order-check').checked));const visible=checks.filter(c=>!c.closest('tr').hidden);if(all){all.checked=visible.length>0&&visible.every(c=>c.checked);all.indeterminate=visible.some(c=>c.checked)&&!all.checked}};checks.forEach(c=>c.addEventListener('change',sync));all?.addEventListener('change',()=>{checks.filter(c=>!c.closest('tr').hidden).forEach(c=>c.checked=all.checked);sync()});document.getElementById('selectVisible')?.addEventListener('click',()=>{checks.filter(c=>!c.closest('tr').hidden).forEach(c=>c.checked=true);sync()});search?.addEventListener('input',()=>{const q=search.value.trim().toLowerCase();rows.forEach(r=>r.hidden=q!==''&&!r.dataset.search.includes(q));sync()});document.getElementById('packingListForm')?.addEventListener('submit',e=>{if(!checks.some(c=>c.checked)){e.preventDefault();alert('Select at least one order.')}});sync()});
</script>
<?= $this->endSection() ?>
